import React, { useEffect, useState } from "react";

interface Question {
  id: number;
  domain: string;
  question_text: string;
  maturity_level: number;
}

const App: React.FC = () => {
  const [questions, setQuestions] = useState<Question[]>([]);

  useEffect(() => {
    fetch("http://localhost:3001/questions")
      .then((res) => res.json())
      .then((data) => setQuestions(data))
      .catch((err) => console.error("Error fetching questions:", err));
  }, []);

  return (
    <div className="p-6">
      <h1 className="text-2xl font-bold mb-4">Cybersecurity Questions</h1>
      <ul>
        {questions.map((q) => (
          <li key={q.id} className="mb-2">
            <strong>{q.domain}</strong>: {q.question_text} (Level {q.maturity_level})
          </li>
        ))}
      </ul>
    </div>
  );
};

export default App;
